// This example will pull up them menu to summon based on the selected token for a summon of elemental trait with level <= actor level

const maxLevel = token.actor?.level;
const traits = ["elemental"];
const summoner = token?.actor;
const itemUuid = "Compendium.pf2e.spells-srd.Item.lpT6LotUaQPfinjj"

window["pf2e-summons-assistant"].summon({
  summonerActor: summoner,
  itemUuid: itemUuid,
  summonType: "summon",
  summonDetailsGroup: [
    {
        summonLevel: maxLevel ?? 1,
        traits: ["elemental"],
      },
  ],
  config: {}
})
